def total_with_tax(items, tax_rate=TAX_RATE):
    """Calculate total including tax, respecting tax_exempt flag.

    Items may include a boolean key ``tax_exempt``. If true, that item's
    line total is not subject to tax. The function computes the subtotal of all
    items, then adds tax only on the sum of non‑exempt line totals.
    """
    # Compute line total for each item
    line_totals = [line_total(item["qty"], item["unit_price"]) for item in items]
    # Determine which items are taxable (tax_exempt missing or False)
    taxable_totals = [lt for lt, item in zip(line_totals, items) if not item.get("tax_exempt", False)]
    taxable_subtotal = sum(taxable_totals)
    total = sum(line_totals) + taxable_subtotal * tax_rate
    return round(total, 2)
